dashboard.definition:
{
    "dataSources": {
        "ds_kev_count": {
            "type": "ds.search",
            "options": {"query": "| inputlookup kev_lookup.csv | stats count as kev_count"}
        },
        "ds_high_epss_7d": {
            "type": "ds.search",
            "options": {"query": "`cveicu_index` sourcetype=\"cveicu:record\"\n| spath cveMetadata.cveId\n| spath cveMetadata.datePublished\n| rename \"cveMetadata.cveId\" as cve_id, \"cveMetadata.datePublished\" as date_published\n| eval pub_time=strptime(date_published, \"%Y-%m-%dT%H:%M:%S\")\n| where pub_time > relative_time(now(), \"-7d@d\")\n| lookup epss_lookup.csv cve_id OUTPUT epss_score\n| where tonumber(epss_score) > 0.5\n| stats dc(cve_id) as high_epss_count"}
        },
        "ds_risk_table": {
            "type": "ds.search",
            "options": {"query": "| inputlookup risk_priority_lookup.csv\n| sort - epss_score\n| where ($epss_filter$) AND ($kev_filter$)\n| head 100\n| table cve_id cvss_score epss_score in_kev ssvc_exploitation"}
        },
        "ds_risk_trend": {
            "type": "ds.search",
            "options": {"query": "`cveicu_index` sourcetype=\"cveicu:record\"\n| spath cveMetadata.cveId\n| spath cveMetadata.datePublished\n| rename \"cveMetadata.cveId\" as cve_id, \"cveMetadata.datePublished\" as date_published\n| eval _time=strptime(date_published, \"%Y-%m-%dT%H:%M:%S\")\n| where _time > relative_time(now(), \"-30d@d\")\n| lookup epss_lookup.csv cve_id OUTPUT epss_score\n| where tonumber(epss_score) > 0.5\n| timechart span=1d dc(cve_id) as high_epss_cves"}
        }
    },
    "inputs": {
        "input_epss_threshold": {
            "type": "input.dropdown",
            "options": {
                "token": "epss_filter",
                "defaultValue": "1=1",
                "items": [
                    {"label": "All", "value": "1=1"},
                    {"label": "EPSS > 0", "value": "tonumber(epss_score) > 0"},
                    {"label": "EPSS > 0.1", "value": "tonumber(epss_score) > 0.1"},
                    {"label": "EPSS > 0.5", "value": "tonumber(epss_score) > 0.5"},
                    {"label": "EPSS > 0.9", "value": "tonumber(epss_score) > 0.9"}
                ]
            },
            "title": "EPSS Threshold"
        },
        "input_kev_only": {
            "type": "input.dropdown",
            "options": {
                "token": "kev_filter",
                "defaultValue": "1=1",
                "items": [
                    {"label": "All", "value": "1=1"},
                    {"label": "KEV Only", "value": "in_kev=\"true\""}
                ]
            },
            "title": "KEV Filter"
        }
    },
    "layout": {
        "type": "grid",
        "options": {"width": 1440},
        "structure": [
            {"item": "viz_kev_count", "type": "block", "position": {"x": 0, "y": 0, "w": 720, "h": 120}},
            {"item": "viz_high_epss", "type": "block", "position": {"x": 720, "y": 0, "w": 720, "h": 120}},
            {"item": "viz_risk_trend", "type": "block", "position": {"x": 0, "y": 120, "w": 1440, "h": 250}},
            {"item": "viz_risk_table", "type": "block", "position": {"x": 0, "y": 370, "w": 1440, "h": 500}}
        ],
        "globalInputs": ["input_epss_threshold", "input_kev_only"]
    },
    "visualizations": {
        "viz_kev_count": {
            "type": "splunk.singlevalue",
            "dataSources": {"primary": "ds_kev_count"},
            "title": "CVEs in CISA KEV",
            "options": {"majorColor": "#dc4e41"}
        },
        "viz_high_epss": {
            "type": "splunk.singlevalue",
            "dataSources": {"primary": "ds_high_epss_7d"},
            "title": "High-EPSS CVEs (Last 7 Days)",
            "options": {"majorColor": "#f8be34"}
        },
        "viz_risk_trend": {
            "type": "splunk.line",
            "dataSources": {"primary": "ds_risk_trend"},
            "title": "High-EPSS CVEs Per Day (Last 30 Days)"
        },
        "viz_risk_table": {
            "type": "splunk.table",
            "dataSources": {"primary": "ds_risk_table"},
            "title": "CVEs by EPSS Score",
            "options": {"count": 20}
        }
    },
    "title": "Risk Priority",
    "description": "CVEs ranked by EPSS, KEV, and CVSS enrichment"
}
